        long_runs = [r for r in runs if r[1] - r[0] + 1 >= 2]
        if long_runs:
            end = long_runs[-1][1]
            for k in range(end + 1, n):
                new[k] = 1
        for s, e in runs:
            if e - s + 1 == 1:
                new[s] = 1
        out.append(new)
    return out
